c=read(P/'checks.json');refs=read(S/'references.json');assert row(S/'index.json')==c['sourceIndex']
correction=dict(schemaVersion=1,blockedSourceIndex=c['sourceIndex'],id='CLOCK-PACKAGE-LOAD-REPEAT-BOOKEND-M1',source='loader.mjs:171-175 versus209-210',problem='Second load rejects handleIssued before Capture/try/finally, so no prior protection recheck is run. Stored59 tests cover repeated componentize, not repeated load.',required=['Preserve v1 and this HOLD unchanged.','A genuine versioned successor must retain the latest genuine Source/package/environment/native/TMP protection recheck from the first load.','Every subsequent forbidden loader invocation must refuse without reentering package loading and execute that retained recheck in a finally path, including invalid second-load config.','Before the full load context exists, retain the actual captured-file recheck once Capture is created; when the complete check exists, retain it without rebinding native/helper metadata or globals.','Test the actual reusable gate/caller seam using pure injected contexts: one successful/partial-failed load, replacement by complete recheck, repeated valid/invalid call, retained recheck failure, zero second package/body calls.','Preserve all fixed package/artifact/proof/capability/native-caller/fresh-process requirements and new independent peer/Root NULL gates.'],grantsActionAuthority=False)
write('required-correction-contract.json',correction)
r=dict(schemaVersion=1,state='INDEPENDENT_CLOCK_PACKAGE_LOADER_SOURCE_REVIEW_HELD_V1',sourceIndexSha256=c['sourceIndex']['sha256'],sourceOnly=True,sourceReviewPassed=False,ownerActionsInvoked=False,hostActionsInvoked=False,packageImportOrComponentizeActionsInvoked=False,disposition='HOLD_FOR_SECOND_LOAD_PROTECTION_BOOKEND',sourceIndex=c['sourceIndex'],checks=row(P/'checks.json'),coverage=c,blocker=correction,otherFindings=['Genuine0.23 source+options API/version, full4889 regulars21 aliases25 artifacts, private membership/modes and six proof/Source families are authenticated.','cc5 tools build, bfea partial core successes within failed phase, and4da metadata continuation compose without promoting the failed adapter phase.','Actual87777 adapter is explicit; genuine0.2.10 capability selection/final audit remains separate from encoded0.2.0 metadata graph.','Native admission remains separately caller-owned; full sidecar/hash/Release checks here are consistency only, not a native classifier.','Construction handle attempts have a correct finally recheck; one-load guard does not. No other concrete source blocker found in bounded review.'],requiredExactInputs=dict(references=row(S/'references.json'),loader=row(S/'loader.mjs'),packageInventory=refs['packageInventory'],toolsBuildReview=refs['toolsBuildReview'],failedAdapterPhaseReview=refs['failedAdapterPhaseReview'],metadataReview=refs['metadataReview'],prunedAdapter=refs['prunedAdapter'],capabilityPolicy=refs['capabilityPolicy'],callerContract=row(S/'caller-contract.json')),scopeLimitations=['No package/helper/API/pruner/normalizer/metadata decoder/componentize/Wizer/engine/guest or process action invoked by reviewer.','Stored59 pure tests and two grammar checks authenticated, not rerun; this review uses independent read/hash/static checks.','Fresh caller/process/native admission/owned watchdog/raw artifacts/final actual-result and runtime gates remain required.'],actualPackageImport=None,actualComponent=None,grantsAnyActionAuthority=False)
write('results.json',r)
write('result-contract.json',dict(schemaVersion=1,requiredFixedValues={k:r[k]for k in ['schemaVersion','state','sourceIndexSha256','sourceOnly','sourceReviewPassed','ownerActionsInvoked','hostActionsInvoked','packageImportOrComponentizeActionsInvoked']},results=row(P/'results.json'),requiredCorrection=row(P/'required-correction-contract.json'),grantsAnyActionAuthority=False))
files=[]
for p in sorted(P.iterdir()):
 if p.name!='index.json':x=row(p);x['path']=p.name;files.append(x)
